package org.bukkit.event.player;import org.bukkit.entity.*;import org.bukkit.inventory.EquipmentSlot;public class PlayerInteractEntityEvent {private final Player player;private final Entity entity;private final EquipmentSlot hand;private boolean cancelled;public PlayerInteractEntityEvent(Player p,Entity e,EquipmentSlot h){player=p;entity=e;hand=h;}public Entity getRightClicked(){return entity;}public Player getPlayer(){return player;}public EquipmentSlot getHand(){return hand;}public void setCancelled(boolean b){cancelled=b;}public boolean isCancelled(){return cancelled;}}
